fn solve(a: i8, b: i8, c: i8) -> i8 {
    // Sort the sides so that x <= y <= z
    let mut sides = [a, b, c];
    sides.sort_unstable();
    let x = sides[0];
    let y = sides[1];
    let z = sides[2];

    // If already a valid triangle, no operations are needed.
    if x + y > z {
        0
    } else {
        // Otherwise, we need (z - (x + y) + 1) increments on the smaller sides
        z - (x + y) + 1
    }
}

#[cfg(test)]
mod tests {
    use super::solve;

    #[test]
    fn already_triangle() {
        assert_eq!(solve(3, 4, 5), 0);
        assert_eq!(solve(10, 10, 10), 0);
        assert_eq!(solve(2, 3, 4), 0);
    }

    #[test]
    fn need_operations() {
        // 1 + 2 <= 3 so need (3 - (1+2) + 1) = 1
        assert_eq!(solve(1, 2, 3), 1);
        // 1 + 1 <= 5 so need (5 - (1+1) + 1) = 4
        assert_eq!(solve(1, 1, 5), 4);
        // unordered inputs
        assert_eq!(solve(5, 1, 1), 4);
        assert_eq!(solve(2, 5, 2), 2); // need to go from (2,2,5) to sum>5
    }
}